/**
 * Orders represent your intent to purchase a particular Climate product. When you create an order, the
 * payment is deducted from your merchant balance.
 */
export type ClimateOrderModel = {
  /**
   * Total amount of [Frontier](https://frontierclimate.com/)'s service fees in the currency's smallest unit.
   */
  'amount_fees': number;
  /**
   * Total amount of the carbon removal in the currency's smallest unit.
   */
  'amount_subtotal': number;
  /**
   * Total amount of the order including fees in the currency's smallest unit.
   */
  'amount_total': number;
  'beneficiary'?: ClimateRemovalsBeneficiaryModel | undefined;
  /**
   * Time at which the order was canceled. Measured in seconds since the Unix epoch.
   */
  'canceled_at': number | null;
  /**
   * Reason for the cancellation of this order.
   */
  'cancellation_reason': 'expired' | 'product_unavailable' | 'requested' | null;
  /**
   * For delivered orders, a URL to a delivery certificate for the order.
   */
  'certificate': string | null;
  /**
   * Time at which the order was confirmed. Measured in seconds since the Unix epoch.
   */
  'confirmed_at': number | null;
  /**
   * Time at which the object was created. Measured in seconds since the Unix epoch.
   */
  'created': number;
  /**
   * Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase, representing the currency for this order.
   */
  'currency': string;
  /**
   * Time at which the order's expected_delivery_year was delayed. Measured in seconds since the Unix epoch.
   */
  'delayed_at': number | null;
  /**
   * Time at which the order was delivered. Measured in seconds since the Unix epoch.
   */
  'delivered_at': number | null;
  /**
   * Details about the delivery of carbon removal for this order.
   */
  'delivery_details': ClimateRemovalsOrderDeliveriesModel[];
  /**
   * The year this order is expected to be delivered.
   */
  'expected_delivery_year': number;
  /**
   * Unique identifier for the object.
   */
  'id': string;
  /**
   * Has the value `true` if the object exists in live mode or the value `false` if the object exists in test mode.
   */
  'livemode': boolean;
  /**
   * Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.
   */
  'metadata': {
  [key: string]: string;
};
  /**
   * Quantity of carbon removal that is included in this order.
   */
  'metric_tons': string;
  /**
   * String representing the object's type. Objects of the same type share the same value.
   */
  'object': 'climate.order';
  /**
   * Unique ID for the Climate `Product` this order is purchasing.
   */
  'product': string | ClimateProductModel;
  /**
   * Time at which the order's product was substituted for a different product. Measured in seconds since the Unix epoch.
   */
  'product_substituted_at': number | null;
  /**
   * The current status of this order.
   */
  'status': 'awaiting_funds' | 'canceled' | 'confirmed' | 'delivered' | 'open';
};

/**
 * Occurs when a Climate order is canceled.
 */
export type ClimateOrderCanceledModel = {
  'object': ClimateOrderModel;
};

/**
 * Occurs when a Climate order is created.
 */
export type ClimateOrderCreatedModel = {
  'object': ClimateOrderModel;
};

/**
 * Occurs when a Climate order is delayed.
 */
export type ClimateOrderDelayedModel = {
  'object': ClimateOrderModel;
};

/**
 * Occurs when a Climate order is delivered.
 */
export type ClimateOrderDeliveredModel = {
  'object': ClimateOrderModel;
};

/**
 * Occurs when a Climate order's product is substituted for another.
 */
export type ClimateOrderProductSubstitutedModel = {
  'object': ClimateOrderModel;
};

/**
 * A Climate product represents a type of carbon removal unit available for reservation.
 * You can retrieve it to see the current price and availability.
 */
export type ClimateProductModel = {
  /**
   * Time at which the object was created. Measured in seconds since the Unix epoch.
   */
  'created': number;
  /**
   * Current prices for a metric ton of carbon removal in a currency's smallest unit.
   */
  'current_prices_per_metric_ton': {
  [key: string]: ClimateRemovalsProductsPriceModel;
};
  /**
   * The year in which the carbon removal is expected to be delivered.
   */
  'delivery_year': number | null;
  /**
   * Unique identifier for the object. For convenience, Climate product IDs are human-readable strings
   * that start with `climsku_`. See [carbon removal inventory](https://stripe.com/docs/climate/orders/carbon-removal-inventory)
   * for a list of available carbon removal products.
   */
  'id': string;
  /**
   * Has the value `true` if the object exists in live mode or the value `false` if the object exists in test mode.
   */
  'livemode': boolean;
  /**
   * The quantity of metric tons available for reservation.
   */
  'metric_tons_available': string;
  /**
   * The Climate product's name.
   */
  'name': string;
  /**
   * String representing the object's type. Objects of the same type share the same value.
   */
  'object': 'climate.product';
  /**
   * The carbon removal suppliers that fulfill orders for this Climate product.
   */
  'suppliers': ClimateSupplierModel[];
};

