export type PaymentMethodCardModel = {
  /**
   * Card brand. Can be `amex`, `cartes_bancaires`, `diners`, `discover`, `eftpos_au`, `jcb`, `link`, `mastercard`, `unionpay`, `visa` or `unknown`.
   */
  'brand': string;
  /**
   * Checks on Card address and CVC if provided.
   */
  'checks': PaymentMethodCardChecksModel | null;
  /**
   * Two-letter ISO code representing the country of the card. You could use this attribute to get a sense of the international breakdown of cards you've collected.
   */
  'country': string | null;
  /**
   * A high-level description of the type of cards issued in this range. (For internal use only and not typically available in standard API requests.)
   */
  'description'?: string | null | undefined;
  /**
   * The brand to use when displaying the card, this accounts for customer's brand choice on dual-branded cards. Can be `american_express`, `cartes_bancaires`, `diners_club`, `discover`, `eftpos_australia`, `interac`, `jcb`, `mastercard`, `union_pay`, `visa`, or `other` and may contain more values in the future.
   */
  'display_brand': string | null;
  /**
   * Two-digit number representing the card's expiration month.
   */
  'exp_month': number;
  /**
   * Four-digit number representing the card's expiration year.
   */
  'exp_year': number;
  /**
   * Uniquely identifies this particular card number. You can use this attribute to check whether two customers who’ve signed up with you are using the same card number, for example. For payment methods that tokenize card information (Apple Pay, Google Pay), the tokenized number might be provided instead of the underlying card number.
   * 
   * *As of May 1, 2021, card fingerprint in India for Connect changed to allow two fingerprints for the same card---one for India and one for the rest of the world.*
   */
  'fingerprint'?: string | null | undefined;
  /**
   * Card funding type. Can be `credit`, `debit`, `prepaid`, or `unknown`.
   */
  'funding': string;
  /**
   * Details of the original PaymentMethod that created this object.
   */
  'generated_from': PaymentMethodCardGeneratedCardModel | null;
  /**
   * Issuer identification number of the card. (For internal use only and not typically available in standard API requests.)
   */
  'iin'?: string | null | undefined;
  /**
   * The name of the card's issuing bank. (For internal use only and not typically available in standard API requests.)
   */
  'issuer'?: string | null | undefined;
  /**
   * The last four digits of the card.
   */
  'last4': string;
  /**
   * Contains information about card networks that can be used to process the payment.
   */
  'networks': NetworksModel | null;
  /**
   * Status of a card based on the card issuer.
   */
  'regulated_status': 'regulated' | 'unregulated' | null;
  /**
   * Contains details on how this Card may be used for 3D Secure authentication.
   */
  'three_d_secure_usage': ThreeDSecureUsageModel | null;
  /**
   * If this Card is part of a card wallet, this contains the details of the card wallet.
   */
  'wallet': PaymentMethodCardWalletModel | null;
};

export type PaymentMethodCardChecksModel = {
  /**
   * If a address line1 was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.
   */
  'address_line1_check': string | null;
  /**
   * If a address postal code was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.
   */
  'address_postal_code_check': string | null;
  /**
   * If a CVC was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.
   */
  'cvc_check': string | null;
};

export type PaymentMethodCardGeneratedCardModel = {
  /**
   * The charge that created this object.
   */
  'charge': string | null;
  /**
   * Transaction-specific details of the payment method used in the payment.
   */
  'payment_method_details': CardGeneratedFromPaymentMethodDetailsModel | null;
  /**
   * The ID of the SetupAttempt that generated this PaymentMethod, if any.
   */
  'setup_attempt': string | SetupAttemptModel | null;
};

