/**
 * A Payment Record is a resource that allows you to represent payments that occur on- or off-Stripe.
 * For example, you can create a Payment Record to model a payment made on a different payment processor,
 * in order to mark an Invoice as paid and a Subscription as active. Payment Records consist of one or
 * more Payment Attempt Records, which represent individual attempts made on a payment network.
 */
export type PaymentRecordModel = {
  'amount': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_authorized': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_canceled': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_failed': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_guaranteed': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_refunded': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  'amount_requested': PaymentsPrimitivesPaymentRecordsResourceAmountModel;
  /**
   * ID of the Connect application that created the PaymentRecord.
   */
  'application': string | null;
  /**
   * Time at which the object was created. Measured in seconds since the Unix epoch.
   */
  'created': number;
  /**
   * Customer information for this payment.
   */
  'customer_details': PaymentsPrimitivesPaymentRecordsResourceCustomerDetailsModel | null;
  /**
   * Indicates whether the customer was present in your checkout flow during this payment.
   */
  'customer_presence': 'off_session' | 'on_session' | null;
  /**
   * An arbitrary string attached to the object. Often useful for displaying to users.
   */
  'description': string | null;
  /**
   * Unique identifier for the object.
   */
  'id': string;
  /**
   * ID of the latest Payment Attempt Record attached to this Payment Record.
   */
  'latest_payment_attempt_record': string | null;
  /**
   * Has the value `true` if the object exists in live mode or the value `false` if the object exists in test mode.
   */
  'livemode': boolean;
  /**
   * Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.
   */
  'metadata': {
  [key: string]: string;
};
  /**
   * String representing the object's type. Objects of the same type share the same value.
   */
  'object': 'payment_record';
  /**
   * Information about the Payment Method debited for this payment.
   */
  'payment_method_details': PaymentsPrimitivesPaymentRecordsResourcePaymentMethodDetailsModel | null;
  'processor_details': PaymentsPrimitivesPaymentRecordsResourceProcessorDetailsModel;
  /**
   * Shipping information for this payment.
   */
  'shipping_details': PaymentsPrimitivesPaymentRecordsResourceShippingDetailsModel | null;
};

